// Improved Express Application with Error Handling, Input Validation, and Security

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');
const createError = require('http-errors');
const winston = require('winston');

const app = express();

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.File({ filename: 'error.log', level: 'error' })],
});

// Middleware
app.use(express.json());
app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') || 'https://trusted-domain.com' }));
app.use(morgan('combined', { stream: { write: (message) => logger.info(message.trim()) } }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get(
  '/users',
  query('id').optional().isInt().toInt(), // Validate optional ID parameter
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const { id } = req.query;
    const filteredUsers = id ? users.filter(user => user.id === id) : users;
    res.json(filteredUsers);
  }
);

// 404 handler
app.use((req, res, next) => {
  next(createError(404, 'Not Found'));
});

// Error-handling middleware
app.use((err, req, res, next) => {
  logger.error(err.stack);
  res.status(err.status || 500).json({
    error: {
      message: err.message || 'Internal Server Error',
      status: err.status || 500,
    },
  });
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

// Test script to verify connectivity to services using environment variables
// Run with: node -r dotenv/config test_credentials.js dotenv_config_path=.env.test

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg'); // PostgreSQL client
const AWS = require('aws-sdk');
const Stripe = require('stripe');
const Anthropic = require('@anthropic-ai/sdk');
const Logfire = require('@logfire/node');

// --- Test PostgreSQL Database Connection ---
async function testDatabaseConnection() {
  console.log('\n🔍 Testing PostgreSQL Database Connection...');
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ DATABASE_URL not set.');
    return false;
  }

  try {
    const pool = new Pool({ connectionString: dbUrl, ssl: { rejectUnauthorized: false } });
    const client = await pool.connect();
    await client.query('SELECT 1'); // Simple query to test connectivity
    client.release();
    await pool.end();
    console.log('✅ Database connection successful.');
    return true;
  } catch (error) {
    console.error('❌ Database connection failed:', error.message);
    return false;
  }
}

// --- Test AWS Credentials ---
async function testAwsCredentials() {
  console.log('\n🔍 Testing AWS Credentials...');
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY not set.');
    return false;
  }

  try {
    const sts = new AWS.STS({
      accessKeyId,
      secretAccessKey,
    });
    await sts.getCallerIdentity().promise(); // Test if credentials are valid
    console.log('✅ AWS credentials are valid.');
    return true;
  } catch (error) {
    console.error('❌ AWS credentials test failed:', error.message);
    return false;
  }
}

// --- Test Stripe API Key ---
async function testStripeKey() {
  console.log('\n🔍 Testing Stripe API Key...');
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    console.log('❌ STRIPE_SECRET_KEY not set.');
    return false;
  }

  try {
    const stripe = new Stripe(stripeKey);
    await stripe.balance.retrieve(); // Test if key is valid
    console.log('✅ Stripe API key is valid.');
    return true;
  } catch (error) {
    console.error('❌ Stripe API key test failed:', error.message);
    return false;
  }
}

// --- Test Anthropic API Key ---
async function testAnthropicKey() {
  console.log('\n🔍 Testing Anthropic API Key...');
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
  if (!anthropicKey) {
    console.log('❌ ANTHROPIC_API_KEY not set.');
    return false;
  }

  try {
    const anthropic = new Anthropic({ apiKey: anthropicKey });
    await anthropic.messages.create({
      model: 'claude-3-opus-20240229',
      max_tokens: 1,
      messages: [{ role: 'user', content: 'Hello' }],
    }); // Test if key is valid
    console.log('✅ Anthropic API key is valid.');
    return true;
  } catch (error) {
    console.error('❌ Anthropic API key test failed:', error.message);
    return false;
  }
}

// --- Test Logfire Token ---
async function testLogfireToken() {
  console.log('\n🔍 Testing Logfire Token...');
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (!logfireToken) {
    console.log('❌ LOGFIRE_TOKEN not set.');
    return false;
  }

  try {
    const logfire = Logfire.createClient(logfireToken);
    await logfire.info('Test message'); // Test if token is valid
    console.log('✅ Logfire token is valid.');
    return true;
  } catch (error) {
    console.error('❌ Logfire token test failed:', error.message);
