// Secure Express Application with Error Handling and Input Validation
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const cors = require('cors');
const { query, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet());
app.use(express.json());
app.use(morgan('combined'));

// CORS Configuration (restrict to trusted domains)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
}));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Health Check (No input validation needed)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users Endpoint with Input Validation
app.get(
  '/users',
  [
    query('id').optional().isInt().withMessage('ID must be an integer'),
    query('email').optional().isEmail().withMessage('Invalid email format'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Centralized Error Handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

// Uncaught Exception Handling
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

// Script to verify environment credentials (stale checks)
const { Client } = require('pg'); // PostgreSQL client
const axios = require('axios'); // For API key validation
const AWS = require('aws-sdk'); // For AWS credentials validation
const stripe = require('stripe'); // For Stripe key validation

handleError = (error, context) => {
  console.error(`❌ [${context}] Failed:`, error.message);
  process.exitCode = 1;
};

// Check PostgreSQL Database Connection
async function checkDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('⚠️  DATABASE_URL is not set. Skipping database check.');
    return;
  }

  const client = new Client({ connectionString: dbUrl });
  try {
    console.log('🔍 Testing database connection...');
    await client.connect();
    const res = await client.query('SELECT 1');
    console.log('✅ Database connection successful!');
  } catch (error) {
    handleError(error, 'Database');
  } finally {
    await client.end();
  }
}

// Check AWS Credentials
async function checkAWS() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    console.log('⚠️  AWS credentials are not set. Skipping AWS check.');
    return;
  }

  const sts = new AWS.STS({
    accessKeyId,
    secretAccessKey,
  });

  try {
    console.log('🔍 Testing AWS credentials...');
    await sts.getCallerIdentity().promise();
    console.log('✅ AWS credentials are valid!');
  } catch (error) {
    handleError(error, 'AWS');
  }
}

// Check Stripe Key
async function checkStripe() {
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (!stripeKey) {
    console.log('⚠️  STRIPE_SECRET_KEY is not set. Skipping Stripe check.');
    return;
  }

  try {
    console.log('🔍 Testing Stripe key...');
    const stripeInstance = stripe(stripeKey);
    await stripeInstance.balance.retrieve();
    console.log('✅ Stripe key is valid!');
  } catch (error) {
    handleError(error, 'Stripe');
  }
}

// Check Anthropic API Key
async function checkAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('⚠️  ANTHROPIC_API_KEY is not set. Skipping Anthropic check.');
    return;
  }

  try {
    console.log('🔍 Testing Anthropic API key...');
    const response = await axios.post(
      'https://api.anthropic.com/v1/complete',
      { prompt: '\n\nHuman: Hello', max_tokens_to_sample: 1 },
      { headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' } }
    );
    if (response.data?.error) throw new Error(response.data.error.message);
    console.log('✅ Anthropic API key is valid!');
  } catch (error) {
    handleError(error, 'Anthropic');
  }
}

// Run all checks
async function runChecks() {
  console.log('🔎 Verifying environment credentials...\n');
  await checkDatabase();
  await checkAWS();
  await checkStripe();
  await checkAnthropic();

  if (process.exitCode === 1) {
    console.log('\n❌ Some credentials are invalid or stale.');
  } else {
    console.log('\n✅ All credentials are valid!');
  }
}

runChecks();

