  }
}

async function testAPIKey(apiName, url, headers) {
  if (!process.env[`${apiName}_API_KEY`]) {
    console.log(`⚠️  No ${apiName}_API_KEY set in .env. Skipping ${apiName} test.`);
    return;
  }

  try {
    const response = await axios.get(url, { headers });
    console.log(`✅ ${apiName} API test successful.`, response.status);
  } catch (error) {
    console.error(`❌ ${apiName} API test failed:`, error.response?.data || error.message);
  }
}

// Run tests
(async () => {
  // Test PostgreSQL
  await testDatabaseConnection();

  // Test AWS (example)
  await testAPIKey(
    'AWS',
    'https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-15',
    { Authorization: `AWS4-HMAC-SHA256 Credential=${process.env.AWS_ACCESS_KEY_ID}/...` }
  );

  // Test Anthropic (example)
  await testAPIKey(
    'ANTHROPIC',
    'https://api.anthropic.com/v1/complete',
    { 'x-api-key': process.env.ANTHROPIC_API_KEY }
  );
})();
