// Secure Express Application
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');
require('express-async-errors'); // Handle async errors

// Initialize Express
const app = express();

// Security Middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Prevent large payloads

// CORS Configuration (Adjust in production)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://trusted-domain.com' : '*',
  methods: ['GET'],
}));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests, please try again later.',
});
app.use(limiter);

// Logger Configuration
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.Console()],
});

// Input Validation Middleware
defaultValidation = [
  query('*').escape(), // Basic XSS prevention
];

// Routes
app.get('/health', defaultValidation, (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  defaultValidation,
  // Example: Validate query params
  query('id').optional().isInt().withMessage('ID must be an integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`Validation error: ${errors.array()}`);
      return res.status(400).json({ errors: errors.array() });
    }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global Error Handler
app.use((err, req, res, next) => {
  logger.error(`Error: ${err.message}`);
  res.status(500).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error',
  });
});

// Start Server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;

// Security Checklist:
// 1. Run `npm audit` regularly
// 2. Use HTTPS in production
// 3. Store secrets in environment variables
// 4. Monitor logs for suspicious activity

