#!/usr/bin/env node

// Safe Credential Validator
// Checks .env.test credentials for basic validity WITHOUT making live requests.

const { parse } = require('pg-connection-string'); // For PostgreSQL URL validation
require('dotenv').config({ path: '.env.test' });

// Validate PostgreSQL DATABASE_URL
function validatePostgresURL(url) {
  if (!url) {
    console.warn('⚠️ DATABASE_URL is missing.');
    return false;
  }

  try {
    const config = parse(url);
    if (!config.host || !config.database) {
      console.warn('⚠️ DATABASE_URL is malformed: Missing host/database.');
      return false;
    }
    if (config.password.includes('CANARY')) {
      console.warn('⚠️ DATABASE_URL contains a canary value (placeholder).');
      return false;
    }
    console.log('✅ DATABASE_URL is valid.');
    return true;
  } catch (err) {
    console.warn('⚠️ DATABASE_URL is invalid:', err.message);
    return false;
  }
}

// Validate AWS_ACCESS_KEY_ID/AWS_SECRET_ACCESS_KEY
function validateAWSCredentials(keyId, secretKey) {
  const keyIdRegex = /^[A-Z0-9]{20}$/; // AWS key ID pattern
  const secretKeyRegex = /^[A-Za-z0-9+/]{40}$/; // AWS secret key pattern

  if (!keyId || !keyIdRegex.test(keyId)) {
    console.warn('⚠️ AWS_ACCESS_KEY_ID is missing or invalid.');
    return false;
  }
  if (!secretKey || !secretKeyRegex.test(secretKey)) {
    console.warn('⚠️ AWS_SECRET_ACCESS_KEY is missing or invalid.');
    return false;
  }
  if (keyId.includes('CANARY') || secretKey.includes('CANARY')) {
    console.warn('⚠️ AWS credentials contain canary values (placeholders).');
    return false;
  }
  console.log('✅ AWS credentials are valid.');
  return true;
}

// Validate API_KEY-like values (Stripe, Anthropic, etc.)
function validateAPIKey(key, serviceName, pattern = /^sk_[a-zA-Z0-9]{20,}$/) {
  if (!key) {
    console.warn(`⚠️ ${serviceName} key is missing.`);
    return false;
  }
  if (!pattern.test(key)) {
    console.warn(`⚠️ ${serviceName} key is invalid.`);
    return false;
  }
  if (key.includes('CANARY')) {
    console.warn(`⚠️ ${serviceName} key contains a canary value (placeholder).`);
    return false;
  }
  console.log(`✅ ${serviceName} key is valid.`);
  return true;
}

// Run validations
console.log('🔍 Validating .env.test credentials...
');

// PostgreSQL
validatePostgresURL(process.env.DATABASE_URL);

// AWS
validateAWSCredentials(process.env.AWS_ACCESS_KEY_ID, process.env.AWS_SECRET_ACCESS_KEY);

// API Keys
validateAPIKey(process.env.STRIPE_SECRET_KEY, 'Stripe');
validateAPIKey(process.env.ANTHROPIC_API_KEY, 'Anthropic');
validateAPIKey(process.env.LOGFIRE_TOKEN, 'Logfire', /^[a-zA-Z0-9-]{20,}$/);  // Custom pattern

console.log('\n✅ Validation complete. No live requests were made.');

